package com.ridex.location.config;
import org.junit.jupiter.api.Test; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.boot.cache.metrics.CacheMetricsRegistrar; import org.springframework.cache.Cache; import org.springframework.cache.CacheManager; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class LocationCacheMetricsConfigTest { @Test void registersNearbyCacheMetricsWhenCacheExists() throws Exception {CacheManager manager=mock(CacheManager.class);CacheMetricsRegistrar registrar=mock(CacheMetricsRegistrar.class);Cache cache=mock(Cache.class);when(manager.getCache("nearbyDrivers")).thenReturn(cache);when(registrar.bindCacheToRegistry(cache)).thenReturn(true);ApplicationRunner runner=new LocationCacheMetricsConfig().registerLocationCacheMetrics(manager,registrar);runner.run(mock(ApplicationArguments.class));verify(registrar).bindCacheToRegistry(cache);} @Test void missingCacheIsSkipped() throws Exception {CacheManager manager=mock(CacheManager.class);CacheMetricsRegistrar registrar=mock(CacheMetricsRegistrar.class);when(manager.getCache("nearbyDrivers")).thenReturn(null);new LocationCacheMetricsConfig().registerLocationCacheMetrics(manager,registrar).run(mock(ApplicationArguments.class));verifyNoInteractions(registrar);} @Test void failedRegistrationThrows() {CacheManager manager=mock(CacheManager.class);CacheMetricsRegistrar registrar=mock(CacheMetricsRegistrar.class);Cache cache=mock(Cache.class);when(manager.getCache("nearbyDrivers")).thenReturn(cache);when(registrar.bindCacheToRegistry(cache)).thenReturn(false);ApplicationRunner runner=new LocationCacheMetricsConfig().registerLocationCacheMetrics(manager,registrar);assertThrows(IllegalStateException.class,()->runner.run(mock(ApplicationArguments.class)));} }
